#include <Arduino.h>
#include <DHT.h>
#include <TM1637Display.h>
#include <math.h>

DHT living(7, DHT11), bedroom(8, DHT11);
TM1637Display display(4, 5);
float temp[2] = {NAN, NAN}, hum[2] = {NAN, NAN};
int lightValue[2] = {0, 0};
bool alarmState[2] = {false, false};
const uint8_t leds[2] = {12, 13};
const uint8_t buttons[2] = {2, 3};
bool rawButton[2] = {HIGH, HIGH}, stableButton[2] = {HIGH, HIGH};
unsigned long changedAt[2] = {0, 0};
unsigned long sampledAt = 0, reportAt = 0, rotatedAt = 0;
uint8_t room = 0, item = 0;
bool firstSample = true;

void reportRoom(uint8_t r) {
  Serial.print(r == 0 ? "Living: temperature=" : "Bedroom: temperature=");
  Serial.print(temp[r]);
  Serial.print(" humidity=");
  Serial.print(hum[r]);
  Serial.print(" light=");
  Serial.println(lightValue[r]);
}

void sampleSensors() {
  temp[0] = living.readTemperature();
  hum[0] = living.readHumidity();
  temp[1] = bedroom.readTemperature();
  hum[1] = bedroom.readHumidity();
}

void updateDisplay() {
  float value = item == 0 ? temp[room] : (item == 1 ? hum[room] : (float)lightValue[room]);
  if (isnan(value)) {
    const uint8_t dash[4] = {0x40, 0x40, 0x40, 0x40};
    display.setSegments(dash);
  } else {
    display.showNumberDec((int)round(value), false);
  }
}

void setup() {
  Serial.begin(9600);
  living.begin();
  bedroom.begin();
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(12, OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(12, LOW);
  digitalWrite(13, LOW);
  display.setBrightness(7);
}

void loop() {
  unsigned long now = millis();
  if (firstSample || now - sampledAt >= 2000UL) {
    firstSample = false;
    sampledAt = now;
    sampleSensors();
  }
  lightValue[0] = analogRead(A0);
  lightValue[1] = analogRead(A1);
  for (uint8_t r = 0; r < 2; ++r) {
    bool active = !isnan(temp[r]) && temp[r] > 30.0f && lightValue[r] > 700;
    digitalWrite(leds[r], active ? HIGH : LOW);
    if (active && !alarmState[r]) {
      Serial.print(r == 0 ? "Living" : "Bedroom");
      Serial.println(" abnormal: excessive temperature and light");
    }
    alarmState[r] = active;
  }
  for (uint8_t b = 0; b < 2; ++b) {
    bool level = digitalRead(buttons[b]);
    if (level != rawButton[b]) {
      rawButton[b] = level;
      changedAt[b] = now;
    }
    if (now - changedAt[b] >= 40UL && stableButton[b] != rawButton[b]) {
      stableButton[b] = rawButton[b];
      if (stableButton[b] == LOW) {
        if (b == 0) room = 1 - room;
        else item = (item + 1) % 3;
        rotatedAt = now;
      }
    }
  }
  if (now - rotatedAt >= 2000UL) {
    rotatedAt = now;
    item = (item + 1) % 3;
    if (item == 0) room = 1 - room;
  }
  updateDisplay();
  if (now - reportAt >= 5000UL) {
    reportAt += 5000UL;
    reportRoom(0);
    reportRoom(1);
    for (uint8_t r = 0; r < 2; ++r) {
      if (alarmState[r]) {
        Serial.print(r == 0 ? "Living" : "Bedroom");
        Serial.println(" abnormal: excessive temperature and light");
      }
    }
  }
  delay(10);
}
